LEVEL = 1
CFG = {1: [5, 45, 80], 2: [15, 55, 95], 3: [25, 65, 99]}
TIERS = [(30, "auto"), (70, "one-approver"), (101, "two-approvers")]
for risk in CFG[LEVEL]:
    need = next(label for bound, label in TIERS if risk < bound)
    print("risk %d -> %s" % (risk, need))

