LEVEL = 1
CFG = {1: {"ttl": 60, "waited": 90}, 2: {"ttl": 300, "waited": 120}, 3: {"ttl": 60, "waited": 30}}
ttl, waited = CFG[LEVEL]["ttl"], CFG[LEVEL]["waited"]
if waited <= ttl:
    print("answered in %ds of %ds TTL -> PROCEED" % (waited, ttl))
else:
    print("unanswered after %ds of %ds TTL -> EXPIRED, default DENY" % (waited, ttl))

