LEVEL = 1
CFG = {1: "restart", 2: "schema-migration", 3: "bulk-delete"}
packet = {"who": "svc-indexer", "what": CFG[LEVEL], "why": "scheduled maintenance",
          "reverse": "restore from snapshot", "risk": "medium"}
required = ["who", "what", "why", "reverse"]
complete = all(k in packet and packet[k] for k in required)
print("context packet complete:", complete)
for k in required:
    print(" ", k, "=", packet[k])

